export default SUBJECTS;

export function getSubject(id) {
  return SUBJECTS.find((s) => s.id === id) || null;
}

export function getConcept(subjectId, conceptId) {
  const s = getSubject(subjectId);
  if (!s) return null;
  const c = s.concepts.find((x) => x.id === conceptId) || null;
  return c ? { subject: s, concept: c } : null;
}

export function allConceptIds() {
  return SUBJECTS.flatMap((s) => s.concepts.map((c) => `${s.id}:${c.id}`));
}
